// Common Maven commands invoking different lifecycles

// Clean lifecycle only - removes target/ directory
// Command: mvn clean

// Default lifecycle only - builds up to package phase
// Command: mvn package

// Both lifecycles - clean first, then build
// Command: mvn clean package

// Site lifecycle - generates project documentation
// Command: mvn site

// All three lifecycles can be combined:
// Command: mvn clean package site
// This runs: clean lifecycle → default lifecycle (up to package) → site lifecycle

// Each lifecycle has phases that run in sequence:
// clean lifecycle: pre-clean → clean → post-clean
// default lifecycle: validate → compile → test → package → verify → install → deploy
// site lifecycle: pre-site → site → post-site → site-deploy

// pom.xml snippet showing where phases apply
<project>
  <groupId>com.example</groupId>
  <artifactId>order-service</artifactId>
  <version>1.0.0</version>
  <packaging>jar</packaging> <!-- affects package phase -->

  <dependencies>
    <dependency>
      <groupId>org.springframework.boot</groupId>
      <artifactId>spring-boot-starter-web</artifactId>
      <version>3.2.0</version>
    </dependency>
  </dependencies>
</project>

// Running 'mvn package' executes these phases in order:
// 1. validate - checks pom.xml is valid, all required info present
// 2. compile - compiles src/main/java to target/classes
// 3. test - compiles src/test/java, runs unit tests
// 4. package - bundles target/classes into order-service-1.0.0.jar

// Running 'mvn install' does everything above PLUS:
// 5. verify - runs integration tests if configured
// 6. install - copies JAR to ~/.m2/repository/com/example/order-service/1.0.0/

// Quick compile check during development
// Command: mvn compile
// Result: compiles src/main/java only, no tests run

// Run tests without packaging
// Command: mvn test
// Result: compiles main + test code, runs JUnit tests

// Most common full build command
// Command: mvn clean package
// Result: deletes target/, compiles, tests, creates JAR in target/

// Install to local repo for other projects to use
// Command: mvn install
// Result: everything package does + copies to ~/.m2/repository

// Diagnostic command for dependency issues
// Command: mvn dependency:tree
// Output shows:
// [INFO] com.example:order-service:jar:1.0.0
// [INFO] +- org.springframework.boot:spring-boot-starter-web:jar:3.2.0
// [INFO] |  +- org.springframework.boot:spring-boot-starter:jar:3.2.0
// [INFO] |  |  +- org.springframework.boot:spring-boot:jar:3.2.0
// Shows all direct and transitive dependencies
